import { readFile } from 'node:fs/promises';
import { Script } from 'node:vm';
import { fileURLToPath } from 'node:url';
const url = new URL('../dream-theme-style.js', import.meta.url);
// Execute the canonical generated bytes, with their real filename for V8 coverage.
new Script(await readFile(url, 'utf8'), {filename: fileURLToPath(url)}).runInThisContext();
export const generatedDream = globalThis.createDreamThemeStyle();
